/// <reference types="vite/client" />

declare module 'virtual:content-icons' {
    import type { LucideIcon } from 'lucide-react'

    /**
     * Lucide icons named by `icon:` in page frontmatter or `meta.json`, keyed by
     * name. Generated by `contentIcons()` in `vite.config.ts`.
     */
    const icons: Record<string, LucideIcon | undefined>
    export default icons
}
